// Source of truth for the okLCH color system. `gen.ts` turns these
// definitions into `colors.css` (raw ramps) and `aliases.css`
// (--hue-* / --neutral-* indirection). Tune values here, then run
// `pnpm gen:colors`. Do not edit the generated CSS by hand.
//
// Model follows https://bob.fyi/oklch-colors: a shared luminance scale
// keeps every ramp aligned by step for predictable contrast, and a
// per-step chroma taper pulls saturation down at the light/dark ends to
// stay inside the sRGB gamut.

export const HUE_STEPS = [
  25, 50, 100, 200, 300, 400, 500, 600, 700, 800, 900, 950, 975,
] as const;

// Neutrals add a 75 step so component backgrounds can match the
// saturated ramps' 50 step (see the article's note on the extra step).
export const NEUTRAL_STEPS = [
  25, 50, 75, 100, 200, 300, 400, 500, 600, 700, 800, 900, 950, 975,
] as const;

export type Step = (typeof NEUTRAL_STEPS)[number];

// Lightness per step. Step 0 would be white oklch(1 0 0); 1000 near
// black. 500 lands around a 5:1 contrast vs white (the workhorse).
const LIGHTNESS: Record<Step, number> = {
  25: 0.985,
  50: 0.97,
  75: 0.955,
  100: 0.93,
  200: 0.865,
  300: 0.795,
  400: 0.715,
  500: 0.64,
  600: 0.565,
  700: 0.49,
  800: 0.41,
  900: 0.32,
  950: 0.25,
  975: 0.19,
};

// Chroma multiplier per step. Peaks at 500, tapers toward both ends.
const CHROMA_SCALE: Record<Step, number> = {
  25: 0.08,
  50: 0.14,
  75: 0.18,
  100: 0.26,
  200: 0.46,
  300: 0.68,
  400: 0.88,
  500: 1.0,
  600: 0.96,
  700: 0.86,
  800: 0.72,
  900: 0.56,
  950: 0.44,
  975: 0.34,
};

// Alpha per step for the transparent ramps, derived from the lightness
// curve so overlays read like their opaque counterparts.
const ALPHA: Record<Step, number> = {
  25: 0.015,
  50: 0.03,
  75: 0.045,
  100: 0.07,
  200: 0.135,
  300: 0.205,
  400: 0.285,
  500: 0.36,
  600: 0.435,
  700: 0.51,
  800: 0.59,
  900: 0.68,
  950: 0.75,
  975: 0.81,
};

export interface Ramp {
  hue: number;
  chroma: number;
}

// 17 chromatic ramps spanning the spectrum. Hue angles in oklch
// degrees; chroma is the peak (at the 500 step) before the taper.
export const HUE_RAMPS = {
  ruby: { hue: 12, chroma: 0.2 },
  red: { hue: 25, chroma: 0.21 },
  orange: { hue: 50, chroma: 0.19 },
  gold: { hue: 75, chroma: 0.16 },
  yellow: { hue: 100, chroma: 0.17 },
  lime: { hue: 128, chroma: 0.19 },
  green: { hue: 150, chroma: 0.18 },
  jade: { hue: 168, chroma: 0.15 },
  teal: { hue: 185, chroma: 0.13 },
  cyan: { hue: 210, chroma: 0.13 },
  blue: { hue: 250, chroma: 0.16 },
  navy: { hue: 262, chroma: 0.16 },
  indigo: { hue: 275, chroma: 0.18 },
  violet: { hue: 292, chroma: 0.2 },
  purple: { hue: 310, chroma: 0.22 },
  magenta: { hue: 328, chroma: 0.24 },
  pink: { hue: 350, chroma: 0.22 },
} as const satisfies Record<string, Ramp>;

// 8 neutral ramps: pure black plus subtly tinted grays. Chroma is tiny
// so they stay monochromatic, with a hint of temperature.
export const NEUTRAL_RAMPS = {
  black: { hue: 0, chroma: 0 },
  gray: { hue: 264, chroma: 0.006 },
  zinc: { hue: 90, chroma: 0.005 },
  ash: { hue: 220, chroma: 0.004 },
  sage: { hue: 150, chroma: 0.012 },
  sand: { hue: 80, chroma: 0.014 },
  plum: { hue: 12, chroma: 0.012 },
  steel: { hue: 245, chroma: 0.016 },
} as const satisfies Record<string, Ramp>;

export type HueName = keyof typeof HUE_RAMPS;
export type NeutralName = keyof typeof NEUTRAL_RAMPS;

// Reference peak chroma for the custom hue ramp. Vivid but broadly in
// gamut; the browser clamps any hue that can't reach it at a given step.
const CUSTOM_REF_CHROMA = 0.15;

// Fallback hue angle if --ds-custom-hue is never set (matches blue).
const CUSTOM_FALLBACK_HUE = 250;

function round(value: number, places: number): number {
  const f = 10 ** places;
  return Math.round(value * f) / f;
}

function color(ramp: Ramp, step: Step): string {
  const l = round(LIGHTNESS[step], 4);
  const c = round(ramp.chroma * CHROMA_SCALE[step], 4);
  if (c === 0) return `oklch(${l} 0 0)`;
  return `oklch(${l} ${c} ${ramp.hue})`;
}

function alphaColor(lightness: number, ramp: Ramp | null, step: Step): string {
  const a = ALPHA[step];
  if (!ramp || ramp.chroma === 0) return `oklch(${lightness} 0 0 / ${a})`;
  const c = round(ramp.chroma * CHROMA_SCALE[step], 4);
  return `oklch(${lightness} ${c} ${ramp.hue} / ${a})`;
}

function rampBlock(name: string, ramp: Ramp, steps: readonly Step[]): string {
  return steps
    .map((step) => `  --${name}-${step}: ${color(ramp, step)};`)
    .join("\n");
}

const HEADER =
  "/* GENERATED by packages/ui/src/colors/gen.ts. Do not edit by hand.\n" +
  "   Edit packages/ui/src/colors/ramps.ts, then run `pnpm gen:colors`. */\n";

export function buildColorsCss(): string {
  const hues = (Object.keys(HUE_RAMPS) as HueName[])
    .map((name) => rampBlock(name, HUE_RAMPS[name], HUE_STEPS))
    .join("\n\n");

  const neutrals = (Object.keys(NEUTRAL_RAMPS) as NeutralName[])
    .map((name) => rampBlock(name, NEUTRAL_RAMPS[name], NEUTRAL_STEPS))
    .join("\n\n");

  const blackAlpha = NEUTRAL_STEPS.map(
    (step) => `  --black-alpha-${step}: ${alphaColor(0, null, step)};`,
  ).join("\n");
  const whiteAlpha = NEUTRAL_STEPS.map(
    (step) => `  --white-alpha-${step}: ${alphaColor(1, null, step)};`,
  ).join("\n");
  const grayAlpha = NEUTRAL_STEPS.map(
    (step) =>
      `  --gray-alpha-${step}: ${alphaColor(0, NEUTRAL_RAMPS.gray, step)};`,
  ).join("\n");

  return `${HEADER}\n:root {\n${hues}\n\n${neutrals}\n\n${blackAlpha}\n\n${whiteAlpha}\n\n${grayAlpha}\n}\n`;
}

function aliasOverride(
  attr: string,
  alias: string,
  source: string,
  steps: readonly Step[],
): string {
  const lines = steps
    .map((step) => `  --${alias}-${step}: var(--${source}-${step});`)
    .join("\n");
  return `[data-${attr}="${source}"] {\n${lines}\n}`;
}

export function buildAliasesCss(): string {
  // Defaults: --hue-* points at blue (current accent), --neutral-* at gray.
  const hueDefault = HUE_STEPS.map(
    (step) => `  --hue-${step}: var(--blue-${step});`,
  ).join("\n");
  const neutralDefault = NEUTRAL_STEPS.map(
    (step) => `  --neutral-${step}: var(--gray-${step});`,
  ).join("\n");

  const hueOverrides = (Object.keys(HUE_RAMPS) as HueName[])
    .map((name) => aliasOverride("hue", "hue", name, HUE_STEPS))
    .join("\n\n");
  const neutralOverrides = (Object.keys(NEUTRAL_RAMPS) as NeutralName[])
    .map((name) => aliasOverride("neutral", "neutral", name, NEUTRAL_STEPS))
    .join("\n\n");

  // Custom accent: same locked lightness/chroma curve as every ramp, with
  // the hue angle driven by --ds-custom-hue (set inline by ThemeApplier).
  const customLines = HUE_STEPS.map((step) => {
    const l = round(LIGHTNESS[step], 4);
    const c = round(CUSTOM_REF_CHROMA * CHROMA_SCALE[step], 4);
    return `  --hue-${step}: oklch(${l} ${c} var(--ds-custom-hue, ${CUSTOM_FALLBACK_HUE}));`;
  }).join("\n");
  const customOverride = `[data-hue="custom"] {\n${customLines}\n}`;

  return `${HEADER}\n:root {\n${hueDefault}\n\n${neutralDefault}\n}\n\n${hueOverrides}\n\n${customOverride}\n\n${neutralOverrides}\n`;
}
